#!/usr/bin/env python3
import argparse
import sys

CLASSIFIER_SOURCE = '#!/usr/bin/env python3\nimport argparse\nimport csv\nimport datetime as dt\nimport json\nimport subprocess\nimport urllib.request\nimport urllib.error\nfrom collections import Counter\nfrom urllib.parse import urlsplit, urlunsplit, parse_qsl, urlencode\n\nDEFAULT_MODEL = "qwen/qwen3.8-27b"\nDEFAULT_BASE = "http://127.0.0.1:1234/v1"\n\nSYSTEM = \'\'\'Classify browser tabs for cleanup.\nReturn ONLY one compact JSON object with two arrays.\nFormat exactly as {"close":[ids], "review":[ids]}.\nAny input id not listed is implicitly KEEP.\nDo not give reasons or any other text.\nBe conservative.\nKEEP useful research, articles, documentation, code, academic material,\nongoing work, references, bookings, and events.\nCLOSE only clearly disposable, completed, obsolete, generic, transient,\npromotional, low-value, error, or stale navigation/search pages.\nREVIEW whenever uncertain.\nKeep each reason under 10 words.\'\'\'\n\nGET_TABS = \'\'\'\nset delim to ASCII character 9\ntell application "Google Chrome"\n    set output to ""\n    set wi to 0\n    repeat with w in windows\n        set wi to wi + 1\n        set ti to 0\n        repeat with t in tabs of w\n            set ti to ti + 1\n            set output to output & wi & delim & ti & delim & false & delim & (title of t) & delim & (URL of t) & linefeed\n        end repeat\n    end repeat\n    return output\nend tell\n\'\'\'\n\nTRACKING_KEYS = {\n    "fbclid","gclid","gbraid","wbraid","dclid","msclkid",\n    "mc_cid","mc_eid","igshid","vero_id","yclid"\n}\n\nPROTECTED_HOSTS = {\n    "mail.google.com", "calendar.google.com", "docs.google.com",\n    "drive.google.com", "accounts.google.com", "localhost", "127.0.0.1"\n}\n\ndef osa(script):\n    r = subprocess.run(["osascript", "-"], input=script, text=True, capture_output=True)\n    if r.returncode:\n        raise RuntimeError(r.stderr.strip())\n    return r.stdout\n\ndef get_tabs():\n    rows = []\n    for line in osa(GET_TABS).splitlines():\n        x = line.split("\\t", 4)\n        if len(x) == 5:\n            rows.append({\n                "window": int(x[0]), "tab": int(x[1]), "pinned": False,\n                "title": x[3], "url": x[4]\n            })\n    return rows\n\ndef normalize_url(url):\n    try:\n        s = urlsplit(url)\n        if s.scheme in {"file", "blob", "chrome"}:\n            return url\n        q = []\n        for k, v in parse_qsl(s.query, keep_blank_values=True):\n            kl = k.lower()\n            if kl.startswith("utm_") or kl in TRACKING_KEYS:\n                continue\n            q.append((k, v))\n        path = s.path.rstrip("/") or "/"\n        return urlunsplit((s.scheme.lower(), s.netloc.lower(), path,\n                           urlencode(q, doseq=True), ""))\n    except Exception:\n        return url\n\ndef host_of(url):\n    try:\n        return urlsplit(url).hostname or ""\n    except Exception:\n        return ""\n\ndef protect(row):\n    url = row["url"].lower()\n    host = row["host"]\n    scheme = urlsplit(row["url"]).scheme.lower()\n    if scheme == "file":\n        return "Local file protected"\n    if host in PROTECTED_HOSTS:\n        return "Work or local page protected"\n    if host == "github.com" or host.endswith(".github.com"):\n        return "GitHub page protected"\n    tokens = ("/account", "/signin", "/login", "/inbox", "bank",\n              "wealth", "mychart", "booking-details", "confirmation", "receipt")\n    if any(x in url for x in tokens):\n        return "Account or transaction page protected"\n    return None\n\ndef compact(url, n=180):\n    return url if len(url) <= n else url[:n-3] + "..."\n\ndef ask_qwen(items, args):\n    schema = {\n        "type": "json_schema",\n        "json_schema": {\n            "name": "tab_cleanup",\n            "strict": True,\n            "schema": {\n                "type": "object",\n                "properties": {\n                    "close": {\n                        "type": "array",\n                        "items": {"type": "integer"}\n                    },\n                    "review": {\n                        "type": "array",\n                        "items": {"type": "integer"}\n                    }\n                },\n                "required": ["close", "review"],\n                "additionalProperties": False\n            }\n        }\n    }\n\n    payload = {\n        "model": args.model,\n        "messages": [\n            {"role": "system", "content": SYSTEM},\n            {"role": "user", "content": json.dumps(items, ensure_ascii=False)}\n        ],\n        "response_format": schema,\n        "temperature": 0,\n        "max_tokens": 800,\n        "stream": False\n    }\n\n    # Qwen 3.8 in LM Studio may accept this OpenAI-compatible setting.\n    # If LM Studio rejects it, retry once without the setting.\n    payload["reasoning_effort"] = "none"\n\n    def send(body):\n        req = urllib.request.Request(\n            args.base.rstrip("/") + "/chat/completions",\n            data=json.dumps(body).encode("utf-8"),\n            headers={"Content-Type": "application/json"}\n        )\n        with urllib.request.urlopen(req, timeout=args.timeout) as resp:\n            return json.loads(resp.read().decode("utf-8"))\n\n    try:\n        data = send(payload)\n    except urllib.error.HTTPError as e:\n        if e.code == 400:\n            payload.pop("reasoning_effort", None)\n            data = send(payload)\n        else:\n            raise\n\n    message = data.get("choices", [{}])[0].get("message", {})\n    content = message.get("content") or ""\n\n    if not content:\n        diagnostic = {\n            "message": message,\n            "finish_reason": data.get("choices", [{}])[0].get("finish_reason"),\n            "usage": data.get("usage"),\n        }\n        raise ValueError(\n            "Empty content. Diagnostic: " +\n            json.dumps(diagnostic, ensure_ascii=False)[:1000]\n        )\n\n    result = json.loads(content)\n    close_ids = {int(x) for x in result.get("close", [])}\n    review_ids = {int(x) for x in result.get("review", [])}\n\n    valid_ids = {int(x["id"]) for x in items}\n    close_ids &= valid_ids\n    review_ids &= valid_ids\n    review_ids -= close_ids\n\n    out = {}\n    for ident in valid_ids:\n        if ident in close_ids:\n            out[ident] = ("CLOSE", "Qwen structured classification")\n        elif ident in review_ids:\n            out[ident] = ("REVIEW", "Qwen requested review")\n        else:\n            out[ident] = ("KEEP", "Implicit keep")\n    return out\n\ndef main():\n    p = argparse.ArgumentParser(description="Dry-run Chrome classifier for thousands of tabs")\n    p.add_argument("--batch-size", type=int, default=40)\n    p.add_argument("--model", default=DEFAULT_MODEL)\n    p.add_argument("--base", default=DEFAULT_BASE)\n    p.add_argument("--timeout", type=int, default=90)\n    args = p.parse_args()\n\n    rows = get_tabs()\n    if not rows:\n        raise SystemExit("No Chrome tabs found.")\n    print(f"Found {len(rows)} tabs.")\n\n    for i, r in enumerate(rows, 1):\n        r["id"] = i\n        r["host"] = host_of(r["url"])\n        r["normalized_url"] = normalize_url(r["url"])\n        r["decision"] = ""\n        r["reason"] = ""\n        r["method"] = ""\n\n    counts = Counter(r["normalized_url"] for r in rows if r["normalized_url"])\n    seen = set()\n    pending = []\n\n    for r in rows:\n        u = r["normalized_url"]\n        if r["url"] in {"chrome://newtab/", "about:blank"}:\n            r["decision"], r["reason"], r["method"] = "CLOSE", "Blank tab", "local"\n        elif u and counts[u] > 1 and u in seen:\n            r["decision"], r["reason"], r["method"] = "CLOSE", "Duplicate normalized URL", "local"\n        else:\n            if u:\n                seen.add(u)\n            reason = protect(r)\n            if reason:\n                r["decision"], r["reason"], r["method"] = "KEEP", reason, "protected"\n            else:\n                pending.append(r)\n\n    print(f"{len(rows)-len(pending)} tabs handled locally or protected.")\n    print(f"{len(pending)} tabs need Qwen classification.")\n\n    pending.sort(key=lambda r: (r["host"], r["title"].lower()))\n    total = (len(pending) + args.batch_size - 1) // args.batch_size\n\n    for start in range(0, len(pending), args.batch_size):\n        batch = pending[start:start+args.batch_size]\n        num = start // args.batch_size + 1\n        domains = len(set(r["host"] for r in batch))\n        print(f"Qwen batch {num}/{total} ({len(batch)} tabs, {domains} domains)")\n        payload = [{"id": r["id"], "title": r["title"][:220],\n                    "url": compact(r["normalized_url"])} for r in batch]\n        try:\n            answers = ask_qwen(payload, args)\n        except Exception as e:\n            print("  Batch failed. Marking REVIEW.", str(e)[:120])\n            answers = {}\n        for r in batch:\n            d, reason = answers.get(r["id"], ("REVIEW", "No reliable batch result"))\n            r["decision"], r["reason"] = d, reason\n            r["method"] = "qwen" if r["id"] in answers else "qwen-failed"\n\n    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")\n    filename = f"chrome_tab_report_large_{stamp}.csv"\n    fields = ["id","window","tab","pinned","decision","reason","method",\n              "host","title","url","normalized_url"]\n    with open(filename, "w", newline="", encoding="utf-8") as f:\n        w = csv.DictWriter(f, fieldnames=fields, extrasaction="ignore")\n        w.writeheader()\n        w.writerows(sorted(rows, key=lambda r: r["id"]))\n\n    c = Counter(r["decision"] for r in rows)\n    m = Counter(r["method"] for r in rows)\n    print()\n    print(f"KEEP   {c[\'KEEP\']}")\n    print(f"CLOSE  {c[\'CLOSE\']}")\n    print(f"REVIEW {c[\'REVIEW\']}")\n    print(f"Qwen classified {m[\'qwen\']}")\n    print(f"Qwen unresolved {m[\'qwen-failed\']}")\n    print()\n    print("DRY RUN. This version contains no tab-closing code.")\n    print("Report written to", filename)\n\nif __name__ == "__main__":\n    main()\n'
PLANNER_SOURCE = '#!/usr/bin/env python3\nimport argparse, csv, datetime as dt, html, subprocess\nfrom pathlib import Path\nfrom collections import Counter, defaultdict\nfrom urllib.parse import urlsplit\n\nPROTECTED_HOSTS={"mail.google.com","calendar.google.com","docs.google.com","drive.google.com","accounts.google.com","localhost","127.0.0.1"}\nTOKENS=("/account","/signin","/login","/inbox","bank","wealth","mychart","booking-details","boarding","itinerary","confirmation","receipt")\n\nGET_TABS = """\nset delim to ASCII character 9\ntell application "Google Chrome"\n set output to ""\n set wi to 0\n repeat with w in windows\n  set wi to wi + 1\n  set ti to 0\n  repeat with t in tabs of w\n   set ti to ti + 1\n   set output to output & wi & delim & ti & delim & (title of t) & delim & (URL of t) & linefeed\n  end repeat\n end repeat\n return output\nend tell\n"""\n\nCLOSE_ONE = """\non run argv\n set targetURL to item 1 of argv\n tell application "Google Chrome"\n  repeat with wi from (count of windows) to 1 by -1\n   tell window wi\n    repeat with ti from (count of tabs) to 1 by -1\n     if URL of tab ti is targetURL then\n      close tab ti\n      return "closed"\n     end if\n    end repeat\n   end tell\n  end repeat\n end tell\n return "not-found"\nend run\n"""\n\ndef osa(script,args=None):\n r=subprocess.run(["osascript","-"]+(args or []),input=script,text=True,capture_output=True)\n if r.returncode: raise RuntimeError(r.stderr.strip())\n return r.stdout.strip()\n\ndef protected(url):\n try:\n  p=urlsplit(url); host=p.hostname or ""; low=url.lower()\n  return p.scheme.lower()=="file" or host in PROTECTED_HOSTS or any(x in low for x in TOKENS)\n except Exception: return True\n\ndef action(r):\n if r.get("decision")!="CLOSE": return "LEAVE"\n if protected(r.get("url","")): return "LEAVE_PROTECTED"\n if r.get("method")=="local" and r.get("reason") in {"Duplicate normalized URL","Blank tab"}: return "CLOSE"\n if r.get("method")=="qwen": return "ARCHIVE_THEN_CLOSE"\n return "LEAVE_REVIEW"\n\ndef archive_html(rows,path):\n a=[r for r in rows if r["action"] in {"ARCHIVE_THEN_CLOSE","CLOSE"}]; g=defaultdict(list)\n for r in a: g[r.get("host") or "(no domain)"].append(r)\n parts=["<!doctype html><html><head><meta charset=\'utf-8\'><title>Archived Chrome Tabs</title>",\n "<style>body{font-family:-apple-system,sans-serif;max-width:1100px;margin:40px auto;padding:0 20px}li{margin:9px 0}.u{font-size:12px;color:#666;word-break:break-all}</style></head><body>",\n f"<h1>Archived Chrome Tabs</h1><p>{len(a)} tabs archived {html.escape(dt.datetime.now().isoformat(timespec=\'minutes\'))}</p>"]\n for host in sorted(g):\n  parts.append("<h2>"+html.escape(host)+"</h2><ul>")\n  for r in g[host]:\n   u=r.get("url",""); title=r.get("title") or u or "(untitled)"\n   parts.append("<li><strong>["+html.escape(r["action"])+"]</strong> <a href=\'"+html.escape(u,quote=True)+"\'>"+html.escape(title)+"</a><div class=\'u\'>"+html.escape(u)+"</div></li>")\n  parts.append("</ul>")\n parts.append("</body></html>")\n path.write_text("\\n".join(parts),encoding="utf-8")\n return len(a)\n\ndef main():\n p=argparse.ArgumentParser()\n p.add_argument("report")\n p.add_argument("--apply",action="store_true")\n p.add_argument("--archive")\n a=p.parse_args()\n with open(a.report,newline="",encoding="utf-8") as f: rows=list(csv.DictReader(f))\n for r in rows: r["action"]=action(r)\n\n # Duplicate-safety invariant.\n # For every normalized URL with multiple open-tab records, force at least\n # one copy to remain open, regardless of Qwen\'s classification.\n groups=defaultdict(list)\n for r in rows:\n  u=r.get("normalized_url","")\n  if u: groups[u].append(r)\n\n duplicate_survivors=0\n for u,grp in groups.items():\n  if len(grp)<2: continue\n\n  # Prefer a tab that is already being left open. Otherwise keep the first\n  # original occurrence from the report.\n  survivor=next((r for r in grp if r["action"] in {\n   "LEAVE","LEAVE_PROTECTED","LEAVE_REVIEW","LEAVE_DUPLICATE_SURVIVOR"\n  }),None)\n  if survivor is None:\n   survivor=min(grp,key=lambda r:int(r.get("id") or 10**12))\n\n  # Make the safeguard explicit in the action plan.\n  if survivor["action"] not in {"LEAVE","LEAVE_PROTECTED","LEAVE_REVIEW"}:\n   survivor["action"]="LEAVE_DUPLICATE_SURVIVOR"\n   duplicate_survivors+=1\n\n stamp=dt.datetime.now().strftime("%Y%m%d_%H%M%S")\n arc=Path(a.archive or f"chrome_tab_archive_{stamp}.html")\n plan=Path(f"chrome_tab_action_plan_{stamp}.csv")\n n=archive_html(rows,arc)\n if not arc.exists() or arc.stat().st_size<100: raise SystemExit("Archive verification failed. Nothing closed.")\n fields=list(rows[0].keys()) if rows else ["action"]\n if "action" not in fields: fields.append("action")\n with open(plan,"w",newline="",encoding="utf-8") as f:\n  w=csv.DictWriter(f,fieldnames=fields,extrasaction="ignore"); w.writeheader(); w.writerows(rows)\n c=Counter(r["action"] for r in rows)\n print("Archive verified:",arc); print("Archived entries:",n); print("All planned closures are included in the archive.")\n print("Direct CLOSE planned:",c["CLOSE"]); print("ARCHIVE_THEN_CLOSE planned:",c["ARCHIVE_THEN_CLOSE"])\n print("Protected/left open:",c["LEAVE_PROTECTED"]); print("Forced duplicate survivors:",c["LEAVE_DUPLICATE_SURVIVOR"]); print("Action plan:",plan)\n if not a.apply:\n  print("DRY RUN. No Chrome tabs were closed."); return\n wanted=Counter(r["url"] for r in rows if r["action"] in {"CLOSE","ARCHIVE_THEN_CLOSE"})\n closed=missing=errors=0\n for url,count in wanted.items():\n  for _ in range(count):\n   try:\n    z=osa(CLOSE_ONE,[url])\n    if z=="closed": closed+=1\n    else: missing+=1; break\n   except Exception: errors+=1; break\n print("Closed:",closed); print("Not found:",missing); print("Errors:",errors); print("Archive remains on disk.")\n\nif __name__=="__main__": main()\n'
RESUME_SOURCE = '#!/usr/bin/env python3\nimport argparse, csv, subprocess\nfrom collections import Counter, defaultdict\n\nGET_TABS = """\nset delim to ASCII character 9\ntell application "Google Chrome"\n set output to ""\n set wi to 0\n repeat with w in windows\n  set wi to wi + 1\n  set ti to 0\n  repeat with t in tabs of w\n   set ti to ti + 1\n   set output to output & wi & delim & ti & delim & (URL of t) & linefeed\n  end repeat\n end repeat\n return output\nend tell\n"""\n\nCLOSING_ACTIONS = {"CLOSE", "ARCHIVE_THEN_CLOSE"}\n\ndef osa(script):\n    r = subprocess.run(["osascript", "-"], input=script, text=True,\n                       capture_output=True)\n    if r.returncode:\n        raise RuntimeError(r.stderr.strip())\n    return r.stdout.strip()\n\ndef read_plan(path):\n    with open(path, newline="", encoding="utf-8") as f:\n        rows = list(csv.DictReader(f))\n    if not rows or "action" not in rows[0]:\n        raise SystemExit("This does not look like an action-plan CSV.")\n    return rows\n\ndef live_tabs():\n    raw = osa(GET_TABS)\n    out = []\n    for line in raw.splitlines():\n        x = line.split("\\t", 2)\n        if len(x) == 3:\n            out.append((int(x[0]), int(x[1]), x[2]))\n    return out\n\ndef main():\n    p = argparse.ArgumentParser(\n        description="Resume an existing Chrome tab action plan quickly."\n    )\n    p.add_argument("plan", help="Existing chrome_tab_action_plan CSV")\n    p.add_argument("--apply", action="store_true",\n                   help="Close remaining planned tabs in one Chrome pass")\n    args = p.parse_args()\n\n    rows = read_plan(args.plan)\n    wanted = Counter(\n        r["url"] for r in rows if r.get("action") in CLOSING_ACTIONS\n    )\n    original = Counter(r["url"] for r in rows)\n\n    live = live_tabs()\n    live_counts = Counter(u for _, _, u in live)\n\n    # Infer planned closures that already happened during the interrupted run.\n    already = Counter()\n    for u, n in wanted.items():\n        missing_from_original = max(0, original[u] - live_counts.get(u, 0))\n        already[u] = min(n, missing_from_original)\n\n    remaining = Counter({\n        u: max(0, n - already[u])\n        for u, n in wanted.items()\n    })\n\n    # Select exact live tab coordinates. Never select more copies than planned.\n    selected = []\n    used = Counter()\n    for wi, ti, u in live:\n        if used[u] < remaining.get(u, 0):\n            selected.append((wi, ti, u))\n            used[u] += 1\n\n    planned = sum(wanted.values())\n    done = sum(already.values())\n    left = len(selected)\n    unavailable = sum(remaining.values()) - left\n\n    print(f"Live Chrome tabs: {len(live)}")\n    print(f"Original planned closures: {planned}")\n    print(f"Estimated already closed: {done}")\n    print(f"Remaining planned closures found live: {left}")\n    print(f"Planned tabs no longer found: {unavailable}")\n\n    if not args.apply:\n        print("DRY RUN. No files created and no tabs closed.")\n        return\n\n    if unavailable:\n        print("WARNING: Some planned tabs are no longer present.")\n        print("Only exact live matches will be closed.")\n\n    # Close by original window/tab coordinates, in descending order.\n    # This keeps indexes stable as tabs disappear.\n    by_window = defaultdict(list)\n    for wi, ti, u in selected:\n        by_window[wi].append(ti)\n\n    script = [\n        \'tell application "Google Chrome"\',\n        \'set closedCount to 0\'\n    ]\n    for wi in sorted(by_window, reverse=True):\n        for ti in sorted(by_window[wi], reverse=True):\n            script.extend([\n                f\'if (count of windows) >= {wi} then\',\n                f\' if (count of tabs of window {wi}) >= {ti} then\',\n                f\'  close tab {ti} of window {wi}\',\n                \'  set closedCount to closedCount + 1\',\n                \' end if\',\n                \'end if\'\n            ])\n    script.extend([\'return closedCount\', \'end tell\'])\n\n    print("Closing remaining tabs in one Chrome pass...")\n    result = osa("\\n".join(script))\n    print(f"Closed this pass: {result}")\n    print("Existing archive and action-plan files were not modified.")\n\nif __name__ == "__main__":\n    main()\n'

def run_component(source, argv):
    old_argv = sys.argv[:]
    namespace = {"__name__": "__main__"}
    try:
        sys.argv = argv
        exec(compile(source, argv[0], "exec"), namespace, namespace)
    finally:
        sys.argv = old_argv

def main():
    p = argparse.ArgumentParser(
        description="Standalone Chrome tab cleanup workflow"
    )
    sub = p.add_subparsers(dest="command", required=True)

    c = sub.add_parser("classify")
    c.add_argument("--batch-size", type=int, default=40)
    c.add_argument("--model", default="qwen/qwen3.8-27b")
    c.add_argument("--base", default="http://127.0.0.1:1234/v1")
    c.add_argument("--timeout", type=int, default=90)

    a = sub.add_parser("plan")
    a.add_argument("report")

    s = sub.add_parser("status")
    s.add_argument("plan")

    x = sub.add_parser("apply")
    x.add_argument("plan")
    x.add_argument("--apply", action="store_true")

    args = p.parse_args()

    if args.command == "classify":
        run_component(CLASSIFIER_SOURCE, [
            "classifier",
            "--batch-size", str(args.batch_size),
            "--model", args.model,
            "--base", args.base,
            "--timeout", str(args.timeout),
        ])
    elif args.command == "plan":
        run_component(PLANNER_SOURCE, ["planner", args.report])
    elif args.command == "status":
        run_component(RESUME_SOURCE, ["resume", args.plan])
    elif args.command == "apply":
        argv = ["resume", args.plan]
        if args.apply:
            argv.append("--apply")
        run_component(RESUME_SOURCE, argv)

if __name__ == "__main__":
    main()
